use rusqlite::{Connection,types::ValueRef};
fn literal(v:ValueRef<'_>)->String{match v{ValueRef::Null=>"NULL".into(),ValueRef::Integer(v)=>v.to_string(),ValueRef::Real(v)=>v.to_string(),ValueRef::Text(v)=>format!("'{}'",String::from_utf8_lossy(v).replace('\'',"''")),ValueRef::Blob(v)=>format!("X'{}'",v.iter().map(|b|format!("{b:02x}")).collect::<String>())}}
fn main(){for pending in [false,true]{let s=Connection::open_in_memory().unwrap();let d=Connection::open_in_memory().unwrap();s.execute_batch("CREATE VIRTUAL TABLE docs USING fts5(v); BEGIN; INSERT INTO docs(rowid,v) VALUES(19,'alpha beta');").unwrap();if !pending{s.execute_batch("COMMIT;").unwrap();}let tables:Vec<(String,String)>=s.prepare("SELECT name,sql FROM sqlite_schema WHERE type='table' ORDER BY name").unwrap().query_map([],|r|Ok((r.get(0)?,r.get(1)?))).unwrap().collect::<rusqlite::Result<_>>().unwrap();d.execute_batch(&tables[0].1).unwrap();for (name,_) in &tables[1..]{d.execute_batch(&format!("DELETE FROM \"{name}\";")).unwrap();let mut st=s.prepare(&format!("SELECT * FROM \"{name}\"")).unwrap();let n=st.column_count();let mut rows=st.query([]).unwrap();while let Some(r)=rows.next().unwrap(){let vals=(0..n).map(|i|literal(r.get_ref(i).unwrap())).collect::<Vec<_>>().join(",");d.execute_batch(&format!("INSERT INTO \"{name}\" VALUES({vals});")).unwrap();}}let found:i64=d.query_row("SELECT count(*) FROM docs WHERE docs MATCH 'alpha'",[],|r|r.get(0)).unwrap();println!("pending={pending} matches={found}");assert_eq!(found,1);}}
